import pandas as pd
out={}
for c in ['DL','B6']:
 d=pd.read_csv(f'airlines/{c}.csv').drop_duplicates(); d=d[d.date.between('2025-01-01','2025-02-28') & ~d.cancelled].copy()
 sh=d.sched_dep.str[:2].astype(int)*60+d.sched_dep.str[3:].astype(int); ah=d.actual_dep.str[:2].astype(int)*60+d.actual_dep.str[3:].astype(int); raw=ah-sh
 # recognize actual after midnight only when clock gap is > 60 min; small negatives are legitimate early departures
 delay=raw.where(raw>=-60,raw+1440)
 out[c]={'delayed':int((delay>15).sum()),'completed':len(d)}
 print(c,out[c],'rollover',sum(raw<-60),'early',sum((raw<0)&(raw>=-60)), 'max',delay.max())
print(out, {'delayed':sum(v['delayed'] for v in out.values()),'completed':sum(v['completed'] for v in out.values())})

